CREATE TABLE IF NOT EXISTS staff_sessions (token_hash TEXT PRIMARY KEY, discord_id TEXT NOT NULL, name TEXT NOT NULL, avatar TEXT NOT NULL DEFAULT '', level INTEGER NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS staff_roster (discord_id TEXT PRIMARY KEY, name TEXT NOT NULL, avatar TEXT NOT NULL DEFAULT '', rank TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', first_login INTEGER NOT NULL, last_login INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS staff_rank_log (id INTEGER PRIMARY KEY AUTOINCREMENT, discord_id TEXT NOT NULL, name TEXT NOT NULL, old_rank TEXT NOT NULL, new_rank TEXT NOT NULL, by_id TEXT NOT NULL, by_name TEXT NOT NULL, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS staff_loa (id INTEGER PRIMARY KEY AUTOINCREMENT, discord_id TEXT NOT NULL, name TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL, decided_by TEXT, decided_name TEXT, decided_at INTEGER, note TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_staff_loa_user ON staff_loa (discord_id, status);
CREATE TABLE IF NOT EXISTS staff_announcements (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, author_id TEXT NOT NULL, author_name TEXT NOT NULL, pinned INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS staff_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '');
